contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length);
        bool reverted;
        bool ret;

        if (_tos.length == 0) {
            try c.transfer(_tos, v) returns (bool r) {
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            try c.transfer(_tos, v) returns (bool r) {
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
            }
            assert(!reverted && ret);
        }
    }
}

